class Solution { public: int minSpaceWastedKResizing(vector<int>& nums,int k){int n=nums.size(),INF=1000000000;vector<vector<int>> waste(n,vector<int>(n));for(int left=0;left<n;++left){int maximum=0,sum=0;for(int right=left;right<n;++right){maximum=max(maximum,nums[right]);sum+=nums[right];waste[left][right]=maximum*(right-left+1)-sum;}}vector<vector<int>> dp(k+2,vector<int>(n+1,INF));dp[0][0]=0;for(int groups=1;groups<=k+1;++groups)for(int end=1;end<=n;++end)for(int start=0;start<end;++start)if(dp[groups-1][start]<INF)dp[groups][end]=min(dp[groups][end],dp[groups-1][start]+waste[start][end-1]);int answer=INF;for(int groups=1;groups<=k+1;++groups)answer=min(answer,dp[groups][n]);return answer;} };
